document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("paver-form"),n=document.getElementById("paver-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const t=parseFloat(document.getElementById("paver-length").value),a=parseFloat(document.getElementById("paver-width").value),[s,r]=document.getElementById("paver-size").value.split(","),p=parseFloat(document.getElementById("paver-pattern").value),i=parseFloat(document.getElementById("paver-type").value),o=document.getElementById("paver-project").value;if(t<=0||a<=0)return n.textContent="Please enter valid dimensions.",void 0;const l=t*a,d=l*parseFloat(s),c=d*(1+p),v=Math.ceil(c),u="driveway"===o?12:8,g=l*u/12/27,$=l*("driveway"===o?6:4)/12/27,m=1*l/12/27,h=15*Math.ceil(l/100),x=2*(t+a),y=Math.ceil(x/8),F=l*i,f=35*$,E=45*m,P=.5*h,B=25*y,b=F+f+E+P+B,I=.1*l,w=I+.15*l,D=65*w,M=Math.ceil($/10),T=Math.ceil(m/10);n.innerHTML=`\n        <div class="result-section">\n          <h4>Project Specifications:</h4>\n          <p>Area: ${t}' × ${a}' = ${l} sq ft</p>\n          <p>Paver size: ${r.replace("x",'" × ')}"</p>\n          <p>Pattern waste: ${100*p}%</p>\n          <p>Project type: ${o.charAt(0).toUpperCase()+o.slice(1)}</p>\n        </div>\n        \n        <div class="result-pavers">\n          <h4>Paver Requirements:</h4>\n          <p><strong>${v} pavers needed</strong></p>\n          <p>Base calculation: ${d.toFixed(0)} pavers</p>\n          <p>With waste factor: ${c.toFixed(0)} pavers</p>\n          <p>Pavers per sq ft: ${s}</p>\n          <p>Paver cost: $${F.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-excavation">\n          <h4>Excavation Requirements:</h4>\n          <p><strong>Excavate ${u}" deep</strong></p>\n          <p>Excavation volume: ${g.toFixed(2)} cubic yards</p>\n          <p>Disposal volume: ${g.toFixed(2)} cubic yards</p>\n          <p>Excavation time: ${I.toFixed(1)} hours</p>\n        </div>\n        \n        <div class="result-base">\n          <h4>Base Materials:</h4>\n          <p><strong>${$.toFixed(2)} cubic yards</strong> crushed stone (3/4")</p>\n          <p><strong>${m.toFixed(2)} cubic yards</strong> bedding sand</p>\n          <p><strong>${h} lbs</strong> joint sand (polymeric)</p>\n          <p>Gravel cost: $${f.toFixed(0)}</p>\n          <p>Sand cost: $${E.toFixed(0)}</p>\n          <p>Joint sand cost: $${P.toFixed(0)}</p>\n        </div>\n        \n        <div class="result-accessories">\n          <h4>Installation Accessories:</h4>\n          <p><strong>${y} pieces</strong> edge restraint (8 ft each)</p>\n          <p>Total perimeter: ${x} linear feet</p>\n          <p>Edge restraint cost: $${B.toFixed(0)}</p>\n          <p>Landscape fabric: ${l} sq ft recommended</p>\n        </div>\n        \n        <div class="result-delivery">\n          <h4>Delivery Requirements:</h4>\n          <p>Gravel delivery: ${M} truck loads</p>\n          <p>Sand delivery: ${T} truck loads</p>\n          <p>Paver delivery: Special arrangements for ${v} pavers</p>\n          <p>Delivery timing: Base materials first, pavers last</p>\n        </div>\n        \n        <div class="result-costs">\n          <h4>Total Project Cost:</h4>\n          <p>Pavers: $${F.toFixed(0)}</p>\n          <p>Base materials: $${(f+E+P).toFixed(0)}</p>\n          <p>Edge restraints: $${B.toFixed(0)}</p>\n          <p><strong>Total materials: $${b.toFixed(0)}</strong></p>\n          <p>Professional labor: $${D.toFixed(0)}</p>\n          <p><strong>Total project: $${(b+D).toFixed(0)}</strong></p>\n          <p>Cost per sq ft: $${((b+D)/l).toFixed(2)}</p>\n        </div>\n        \n        <div class="result-timeline">\n          <h4>Installation Timeline:</h4>\n          <p><strong>Day 1:</strong> Excavation and disposal</p>\n          <p><strong>Day 2:</strong> Base gravel installation and compaction</p>\n          <p><strong>Day 3:</strong> Sand leveling and edge restraints</p>\n          <p><strong>Day 4-5:</strong> Paver installation</p>\n          <p><strong>Day 6:</strong> Joint sand and final compaction</p>\n          <p>Total labor: ${w.toFixed(1)} hours</p>\n        </div>\n        \n        <div class="result-tools">\n          <h4>Tools & Equipment Needed:</h4>\n          <p>🚜 Mini excavator or shovels</p>\n          <p>🎢 Plate compactor (rent $75/day)</p>\n          <p>📐 String lines and levels</p>\n          <p>🪚 Wet saw for cutting pavers</p>\n          <p>🧤 Knee pads and work gloves</p>\n          <p>📏 Measuring tape and chalk line</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>Installation Tips:</h4>\n          <p>📞 Call 811 for utility marking</p>\n          <p>🌦️ Avoid installation in wet weather</p>\n          <p>📦 Order 5% extra pavers for future repairs</p>\n          <p>🎯 Start installation from a straight edge</p>\n          <p>💧 Proper drainage is essential</p>\n          <p>⏰ Allow base to settle 24 hours</p>\n        </div>\n      `})});